<?php
namespace App\Interfaces\Http\Controllers\Api\V1\Support;
use App\Application\Audit\AuditWriter;use App\Application\Operations\CommunicationLogService;use App\Domain\Support\TicketStateMachine;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
final class SupportController{
public function store(Request$r,AuditWriter$a){$d=$r->validate(['party_id'=>'nullable|uuid|exists:parties,id','type'=>'required|in:SUPPORT,COMPLAINT,REGULATORY_COMPLAINT','category'=>'required|string|max:64','priority'=>'required|in:LOW,NORMAL,HIGH,URGENT','subject'=>'required|string|max:200','description'=>'required|string|min:20|max:10000','idempotency_key'=>'required|string|max:100']);$t=app(\App\Domain\Tenancy\TenantContext::class)->id();if(isset($d['party_id']))abort_unless(DB::table('tenant_customers')->where(['tenant_id'=>$t,'party_id'=>$d['party_id']])->exists(),404);if($o=DB::table('support_tickets')->where(['tenant_id'=>$t,'idempotency_key'=>$d['idempotency_key']])->first())return response()->json(['data'=>$o]);$id=(string)Str::uuid();$number='TKT-'.now()->format('Ym').'-'.strtoupper(Str::random(8));$hours=match($d['priority']){'URGENT'=>4,'HIGH'=>12,'NORMAL'=>48,default=>96};DB::transaction(function()use($d,$id,$number,$hours,$r,$a,$t){DB::table('support_tickets')->insert([...$d,'id'=>$id,'tenant_id'=>$t,'ticket_number'=>$number,'status'=>'OPEN','sla_due_at'=>now()->addHours($hours),'created_at'=>now(),'updated_at'=>now()]);DB::table('support_ticket_events')->insert(['id'=>(string)Str::uuid(),'support_ticket_id'=>$id,'type'=>'CREATED','to_status'=>'OPEN','actor_id'=>$r->user()?->id,'message'=>$d['description'],'metadata'=>'{}','occurred_at'=>now()]);$a->record('support.ticket.created','support_ticket',$id,['type'=>$d['type'],'priority'=>$d['priority']]);});return response()->json(['data'=>['id'=>$id,'ticket_number'=>$number,'status'=>'OPEN']],201);}
public function transition(Request$r,string$ticket,TicketStateMachine$m,AuditWriter$a){$d=$r->validate(['to_status'=>'required|in:TRIAGED,IN_PROGRESS,WAITING_CUSTOMER,ESCALATED,RESOLVED,CLOSED,REOPENED,CANCELLED','message'=>'required|string|min:5|max:5000','assigned_to'=>'nullable|uuid|exists:users,id']);$t=app(\App\Domain\Tenancy\TenantContext::class)->id();return DB::transaction(function()use($d,$ticket,$m,$a,$r,$t){$o=DB::table('support_tickets')->where(['id'=>$ticket,'tenant_id'=>$t])->lockForUpdate()->first();abort_unless($o,404);$m->assert($o->status,$d['to_status']);$u=['status'=>$d['to_status'],'updated_at'=>now()];if(!empty($d['assigned_to']))$u['assigned_to']=$d['assigned_to'];if($d['to_status']==='RESOLVED')$u['resolved_at']=now();if($d['to_status']==='CLOSED')$u['closed_at']=now();DB::table('support_tickets')->where('id',$ticket)->update($u);DB::table('support_ticket_events')->insert(['id'=>(string)Str::uuid(),'support_ticket_id'=>$ticket,'type'=>'STATUS_CHANGED','from_status'=>$o->status,'to_status'=>$d['to_status'],'actor_id'=>$r->user()->id,'message'=>$d['message'],'metadata'=>'{}','occurred_at'=>now()]);$a->record('support.ticket.transitioned','support_ticket',$ticket,['from'=>$o->status,'to'=>$d['to_status']]);return response()->json(['data'=>['id'=>$ticket,'status'=>$d['to_status']]]);});}
public function communication(Request$r,CommunicationLogService$s){$d=$r->validate(['party_id'=>'nullable|uuid','direction'=>'required|in:INBOUND,OUTBOUND','channel'=>'required|in:PHONE,SMS,EMAIL,WHATSAPP,PORTAL','purpose'=>'required|string|max:24','counterparty'=>'required|string|max:190','summary'=>'required|string|max:5000','ticket_id'=>'nullable|uuid','metadata'=>'array','occurred_at'=>'nullable|date']);$t=app(\App\Domain\Tenancy\TenantContext::class)->id();foreach(['party_id'=>'tenant_customers','ticket_id'=>'support_tickets']as$k=>$table)if(!empty($d[$k]))abort_unless(DB::table($table)->where($k==='party_id'?['tenant_id'=>$t,'party_id'=>$d[$k]]:['tenant_id'=>$t,'id'=>$d[$k]])->exists(),404);return response()->json(['data'=>['id'=>$s->record($t,$d,$r->user()->id)]],201);}}
